function validateField(field) {const value = field.value.trim();let errorMessage = '';if (field.hasAttribute('required') && !value) {errorMessage = `${getFieldLabel(field)}is required and cannot be empty.`;}else if (field.type === 'email' && value && !isValidEmail(value)) {errorMessage = 'Please enter a valid email address (e.g.,name@domain.com).';}else if (field.getAttribute('minlength') && value.length > 0 && value.length < parseInt(field.getAttribute('minlength'))) {errorMessage = `${getFieldLabel(field)}must be at least ${field.getAttribute('minlength')}characters long.`;}else if (field.name === 'message' && value.length > 0 && value.length < 10) {errorMessage = 'Please provide a more detailed message (at least 10 characters).';}else if (field.name === 'name' && value.length > 0 && value.length < 2) {errorMessage = 'Name must be at least 2 characters long.';}if (errorMessage) {showFieldError(field,errorMessage);return false;}else {clearFieldError(field);return true;}}function showFieldError(field,message) {const errorContainer = document.getElementById(`${field.id}-error`);if (errorContainer) {errorContainer.textContent = message;errorContainer.classList.remove('hidden');field.setAttribute('aria-invalid','true');field.classList.add('border-red-500');}}function clearFieldError(field) {const errorContainer = document.getElementById(`${field.id}-error`);if (errorContainer) {errorContainer.textContent = '';errorContainer.classList.add('hidden');field.setAttribute('aria-invalid','false');field.classList.remove('border-red-500');}}function getFieldLabel(field) {const label = field.labels && field.labels[0];if (label) {return label.textContent.replace('*','').trim();}return field.getAttribute('aria-label') || field.name || 'Field';}function isValidEmail(email) {const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;return emailRegex.test(email);}document.addEventListener('DOMContentLoaded',() => {console.log('Contact form validation script loaded');const form = document.getElementById('contact-form');const status = document.getElementById('form-status');if (!form || !status) {console.error('Form or status element not found');return;}const btn = form.querySelector('button[type="submit"]');const label = document.getElementById('btn-label');const spinner = document.getElementById('spinner');const inputs = form.querySelectorAll('input,textarea');inputs.forEach(input => {input.addEventListener('blur',() => validateField(input));input.addEventListener('input',() => clearFieldError(input));});form.addEventListener('submit',async (e) => {e.preventDefault();console.log('Form submitted,validating...');const nameField = document.getElementById('name');const emailField = document.getElementById('email');const messageField = document.getElementById('message');let isValid = true;const invalidFields = [];if (!validateField(nameField)) {isValid = false;invalidFields.push('Name');}if (!validateField(emailField)) {isValid = false;invalidFields.push('Email');}if (!validateField(messageField)) {isValid = false;invalidFields.push('Message');}console.log('Validation result:',{isValid,invalidFields });if (!isValid) {const firstInvalidField = form.querySelector('[aria-invalid="true"]');if (firstInvalidField) {firstInvalidField.focus();}status.textContent = `❌ Please correct ${invalidFields.length}error${invalidFields.length > 1 ? 's' :''}:${invalidFields.join(',')}`;status.className = 'text-red-600 bg-red-50 border border-red-200 rounded-lg p-4 text-center font-semibold mb-4';status.classList.remove('hidden');return;}status.classList.add('hidden');if (btn && label && spinner) {btn.disabled = true;label.textContent = 'Sending…';spinner.classList.remove('hidden');}const fd = new FormData(form);if (fd.get('bot-field')) return;const token = document.querySelector('[name="cf-turnstile-response"]')?.value || '';const payload = {name:fd.get('name'),email:fd.get('email'),message:fd.get('message'),token };try {const res = await fetch('/send-email',{method:'POST',headers:{'Content-Type':'application/json' },body:JSON.stringify(payload) });const json = await res.json();if (json.success) {status.textContent = '✅ Thank you for your message! I\'ll get back to you soon. 🎉';status.className = 'text-green-600 bg-green-50 border border-green-200 rounded-lg p-4 text-center font-semibold mb-4';status.classList.remove('hidden');console.log('✅ Form submitted successfully');form.reset();[nameField,emailField,messageField].forEach(input => {if (input) {input.setAttribute('aria-invalid','false');input.classList.remove('border-red-500');const errorContainer = document.getElementById(`${input.id}-error`);if (errorContainer) {errorContainer.classList.add('hidden');errorContainer.textContent = '';}}});}else {status.textContent = `❌ ${json.error || 'Something went wrong. Please try again.'}`;status.className = 'text-red-600 bg-red-50 border border-red-200 rounded-lg p-4 text-center font-semibold mb-4';status.classList.remove('hidden');}}catch {status.textContent = '❌ Server error. Please check your connection and try again.';status.className = 'text-red-600 bg-red-50 border border-red-200 rounded-lg p-4 text-center font-semibold mb-4';status.classList.remove('hidden');}finally {if (btn && label && spinner) {btn.disabled = false;label.textContent = 'Send Message';spinner.classList.add('hidden');}}});});class AccessibleFormValidation {constructor(formSelector = 'form') {this.forms = document.querySelectorAll(formSelector);this.initializeForms();}initializeForms() {this.forms.forEach(form => {this.setupFormValidation(form);this.setupRealTimeValidation(form);this.setupSubmissionHandling(form);});}setupFormValidation(form) {const inputs = form.querySelectorAll('input,textarea,select');inputs.forEach(input => {const errorId = `${input.id}-error`;if (!document.getElementById(errorId)) {const errorDiv = document.createElement('div');errorDiv.id = errorId;errorDiv.className = 'text-red-600 text-sm hidden';errorDiv.setAttribute('role','alert');errorDiv.setAttribute('aria-live','polite');input.parentNode.appendChild(errorDiv);}const describedBy = input.getAttribute('aria-describedby') || '';if (!describedBy.includes(errorId)) {input.setAttribute('aria-describedby',`${describedBy}${errorId}`.trim());}});}setupRealTimeValidation(form) {const inputs = form.querySelectorAll('input,textarea');inputs.forEach(input => {input.addEventListener('blur',() => {this.validateField(input);});input.addEventListener('input',() => {this.clearFieldError(input);});});}validateField(field) {const value = field.value.trim();let errorMessage = '';if (field.hasAttribute('required') && !value) {errorMessage = `${this.getFieldLabel(field)}is required and cannot be empty.`;}else if (field.type === 'email' && value && !this.isValidEmail(value)) {errorMessage = 'Please enter a valid email address (e.g.,name@domain.com).';}else if (field.minLength && value.length > 0 && value.length < field.minLength) {errorMessage = `${this.getFieldLabel(field)}must be at least ${field.minLength}characters long.`;}else if (field.maxLength && value.length > field.maxLength) {errorMessage = `${this.getFieldLabel(field)}must be no more than ${field.maxLength}characters long.`;}else if (field.name === 'message' && value.length > 0 && value.length < 10) {errorMessage = 'Please provide a more detailed message (at least 10 characters).';}else if (field.name === 'name' && value.length > 0 && value.length < 2) {errorMessage = 'Name must be at least 2 characters long.';}if (errorMessage) {this.showFieldError(field,errorMessage);return false;}else {this.clearFieldError(field);return true;}}showFieldError(field,message) {const errorContainer = document.getElementById(`${field.id}-error`);if (errorContainer) {errorContainer.textContent = message;errorContainer.classList.remove('hidden');field.setAttribute('aria-invalid','true');field.classList.add('border-red-500');if (window.srAnnouncer) {window.srAnnouncer.announce(`Error:${message}`,'assertive');}}}clearFieldError(field) {const errorContainer = document.getElementById(`${field.id}-error`);if (errorContainer) {errorContainer.textContent = '';errorContainer.classList.add('hidden');field.setAttribute('aria-invalid','false');field.classList.remove('border-red-500');}}setupSubmissionHandling(form) {form.addEventListener('submit',(e) => {e.preventDefault();const inputs = form.querySelectorAll('input,textarea');let isValid = true;const invalidFields = [];inputs.forEach(input => {if (!this.validateField(input)) {isValid = false;invalidFields.push(this.getFieldLabel(input));}});if (!isValid) {const firstInvalidField = form.querySelector('[aria-invalid="true"]');if (firstInvalidField) {firstInvalidField.focus();}const statusContainer = document.getElementById('form-status');if (statusContainer) {statusContainer.textContent = `Please correct ${invalidFields.length}error${invalidFields.length > 1 ? 's' :''}:${invalidFields.join(',')}`;statusContainer.className = 'text-red-600 bg-red-50 border border-red-200 rounded-lg p-4 text-center font-semibold mb-4';statusContainer.classList.remove('hidden');}if (window.srAnnouncer) {window.srAnnouncer.announce( `Form contains ${invalidFields.length}error${invalidFields.length > 1 ? 's' :''}. Please correct the following fields:${invalidFields.join(',')}`,'assertive' );}return;}this.handleFormSubmission(form);});}handleFormSubmission(form) {const submitButton = form.querySelector('button[type="submit"]');if (submitButton) {submitButton.setAttribute('aria-disabled','true');submitButton.classList.add('loading');const buttonText = submitButton.querySelector('#btn-label');if (buttonText) {buttonText.textContent = 'Sending...';}}if (window.srAnnouncer) {window.srAnnouncer.announce('Sending message,please wait...','polite');}setTimeout(() => {this.showSubmissionSuccess(form);},2000);}showSubmissionSuccess(form) {const submitButton = form.querySelector('button[type="submit"]');const statusContainer = document.getElementById('form-status');if (submitButton) {submitButton.removeAttribute('aria-disabled');submitButton.classList.remove('loading');const buttonText = submitButton.querySelector('#btn-label');if (buttonText) {buttonText.textContent = 'Send Message';}}if (statusContainer) {statusContainer.className = 'text-green-600 bg-green-50 border border-green-200 rounded-lg p-4 text-center font-semibold mb-4';statusContainer.textContent = '✅ Message sent successfully! I\'ll get back to you soon.';}if (window.srAnnouncer) {window.srAnnouncer.announce('Message sent successfully! I will get back to you soon.','polite');}form.reset();const inputs = form.querySelectorAll('input,textarea');inputs.forEach(input => this.clearFieldError(input));}getFieldLabel(field) {const label = field.labels && field.labels[0];if (label) {return label.textContent.replace('*','').trim();}return field.getAttribute('aria-label') || field.name || 'Field';}isValidEmail(email) {const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;return emailRegex.test(email);}}if (typeof document !== 'undefined') {document.addEventListener('DOMContentLoaded',() => {new AccessibleFormValidation();});}